{
	"name": "opencode-kimi-code-auth",
	"version": "0.1.7",
	"description": "OpenCode OAuth bridge for Kimi Code CLI",
	"type": "module",
	"main": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"default": "./dist/index.js"
		}
	},
	"sideEffects": false,
	"files": [
		"dist/",
		"README.md",
		"LICENSE"
	],
	"engines": {
		"node": ">=20"
	},
	"scripts": {
		"build": "tsc -p tsconfig.build.json",
		"typecheck": "tsc --noEmit",
		"prepublishOnly": "npm run build"
	},
	"publishConfig": {
		"access": "public"
	},
	"dependencies": {
		"@opencode-ai/plugin": "^1.1.59"
	},
	"devDependencies": {
		"@types/node": "^24.10.1",
		"typescript": "^5.0.0"
	},
	"keywords": [
		"opencode",
		"kimi",
		"moonshot",
		"oauth",
		"plugin",
		"auth"
	],
	"author": "Simplereally",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/Simplereally/opencode-kimi-code-auth.git"
	},
	"homepage": "https://github.com/Simplereally/opencode-kimi-code-auth#readme",
	"bugs": {
		"url": "https://github.com/Simplereally/opencode-kimi-code-auth/issues"
	},
	"license": "MIT"
}
